package dev.pocketengine.core;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.Test;import static org.junit.Assert.*;
public final class NativeToolObservationTest {
 private static final String TASK=UUID.randomUUID().toString(),RUN=UUID.randomUUID().toString();
 private static RunControl control(){RunControl original=new RunControl();original.bindHostRun(TASK,RUN,1);return original;}
 private static NativeToolObservation.Identity identity(){return new NativeToolObservation.Identity(TASK,RUN,1,"actual-profile",1,"private","actual-session","actual-space","tab",1,1,"document","observation",1,new NativeToolObservation.Viewport(100,200,0,5,1,new NativeToolObservation.Crop(0,0,100,100),100,100));}
 @Test public void onlyOriginalControlAndOperationCanConsumeOnceAndCloseRemovesPixels()throws Exception{RunControl original=control();byte[] source={1,2,3};NativeToolObservation value=NativeToolObservation.capture("browser_task_observe_visual","actual-op",original,identity(),source,"image/png",()->{});Arrays.fill(source,(byte)9);assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","actual-op",control()));assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","wrong-op",original));var image=value.consume("browser_task_observe_visual","actual-op",original);assertEquals("AQID",image.base64(original));assertFalse(image.metadata().getBoolean("coordinateAuthority"));assertFalse(image.metadata().getBoolean("verified"));assertFalse(image.metadata().toString().contains("AQID"));assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","actual-op",original));value.close();assertThrows(IllegalStateException.class,()->image.base64(original));}
 @Test public void nativeCurrentnessCallbacksNeverHoldCarrierOrImageMonitorDuringClose()throws Exception{RunControl original=control();AtomicReference<NativeToolObservation> holder=new AtomicReference<>();AtomicBoolean block=new AtomicBoolean();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);NativeToolObservation value=NativeToolObservation.capture("browser_task_observe_visual","actual-op",original,identity(),new byte[]{1,2,3},"image/png",()->{if(holder.get()!=null)assertFalse(Thread.holdsLock(holder.get()));if(block.get()){entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));}});holder.set(value);var image=value.consume("browser_task_observe_visual","actual-op",original);block.set(true);ExecutorService worker=Executors.newSingleThreadExecutor();try{Future<?> pending=worker.submit(()->assertThrows(Exception.class,()->image.base64(original)));assertTrue(entered.await(3,TimeUnit.SECONDS));value.close();release.countDown();pending.get(3,TimeUnit.SECONDS);}finally{release.countDown();worker.shutdownNow();assertTrue(worker.awaitTermination(3,TimeUnit.SECONDS));value.close();}}
 @Test public void revokedNativeFrameCannotBeConvertedIntoImageEvenWithSameToolJson()throws Exception{RunControl original=control();AtomicBoolean current=new AtomicBoolean(true);NativeToolObservation value=NativeToolObservation.capture("browser_task_observe_visual","actual-op",original,identity(),new byte[]{1},"image/jpeg",()->{if(!current.get())throw new SecurityException("actual_native_document_changed");});current.set(false);assertThrows(SecurityException.class,()->value.consume("browser_task_observe_visual","actual-op",original));value.close();}
 @Test public void nativeMimeBoundsAndCropAreExplicitRatherThanAJsonScreenshotClaim()throws Exception{RunControl original=control();assertThrows(IllegalArgumentException.class,()->NativeToolObservation.capture("browser_task_observe_visual","op",original,identity(),new byte[]{1},"application/octet-stream",()->{}));assertThrows(IllegalArgumentException.class,()->new NativeToolObservation.Viewport(100,100,0,0,1,new NativeToolObservation.Crop(99,0,2,10),2,10));assertThrows(IllegalArgumentException.class,()->NativeToolObservation.capture("browser_task_observe_visual","op",original,identity(),new byte[0],"image/png",()->{}));}
}
